  <section className="settings-section"><div className="settings-section-heading"><CalendarDays/><div><h3>Calendar connections</h3><p>Sync planned meetings both ways with Google Calendar and Outlook.</p></div></div><p className="inline-status">Only meetings in your Said and Done agenda are linked. Unrelated calendar events stay out of your library; deletions are reported without removing events.</p><div className="settings-actions">{(['google','microsoft'] as const).map(provider=><button key={provider} className={calendarConnections[provider]?'secondary-action':'primary-action'} disabled={!session||calendarBusy} onClick={()=>calendarConnections[provider]?onDisconnectCalendar(provider):onConnectCalendar(provider)}>{calendarConnections[provider]?('Disconnect '+(provider==='google'?'Google Calendar':'Outlook')+' ('+calendarConnections[provider]+')'):('Connect '+(provider==='google'?'Google Calendar':'Outlook'))}</button>)}<button className="secondary-action" disabled={!session||calendarBusy||!Object.keys(calendarConnections).length} onClick={onSyncCalendars}>{calendarBusy?'Syncing…':'Sync both calendars'}</button></div>{calendarStatus&&<p className="inline-status" role="status">{calendarStatus}</p>}{calendarHistory.length>0&&<div className="calendar-history"><b>Recent syncs</b>{calendarHistory.slice(0,5).map((run,i)=><p key={i} className="inline-status">{new Date(run.at).toLocaleString()} · {(run.results||[]).map((r:any)=>r.provider+(r.error?": "+r.error:"")).join(" · ")}</p>)}</div>}</section>
